// HELP's words (backlog "Help (F1 / ?)", UX22): how-to answers, keys and mouse, function keys. Keep this current with
// every user-visible feature or key (Dave); each how-to names its area (HOWTO_AREAS). The tools list comes from the tool
// strip (TOOL_GROUPS) and the hints.
import { KEY_COMMANDS } from './shellKeys'

/** Help's how-tos come in these groups, in this order (review R84: one flat list of 100 was hard to scan). */
export const HOWTO_AREAS = {
	draw: 'Drawing and editing', views: 'Views, tabs and windows', plans: 'Plans: runs, outlets and routes', racks: 'Racks, ports and patching',
	sheets: 'Sheets and issuing', layers: 'Layers and blocks', project: 'Project, floors and files',
} as const
export interface HowTo { area: keyof typeof HOWTO_AREAS; q: string; a: string; featured?: boolean }

export const HOWTO: HowTo[] = [
	{ featured: true, area: 'draw', q: 'Edit labels one after another (outlets, racks, run labels, texts, leaders)', a: 'Double-click a label (or select it and press F2): a box opens on the drawing. Type, then Tab saves and opens the NEXT one of the same kind in reading order (Shift+Tab: the previous one). Enter saves and stops; Esc cancels. Renaming an outlet renames its ports too (it asks first when the panel labels were already printed).' },
	{ area: 'draw', q: 'Renumber, or find and replace in labels', a: 'Select several outlets, racks, labelled shapes or sheets (or click them in order with the Renumber tool): Properties shows Renumber. Its Renumber tab numbers them from a start by a step. Its Find / replace tab changes text in their labels — or, for outlets, only in their port labels (In: port labels). Tick “regular expression” for a pattern: ^ start, $ end, \\d a digit, ( ) a group you reuse as $1 in the replacement. It lists old → new and labels already used before you press Replace; one undo step. In the Outlets table, select outlets: Find/replace… in the bar opens it on them (⋯ › Find / replace in the shown… on every row shown).' },
	{ area: 'draw', q: 'Find what a click will take', a: 'Move the pointer over the drawing: what a click would select gets a thin light-blue outline, and the cursor says what a press does — a cross on a grip, a four-way arrow on something you can drag, a hand on the rest.' },
	{ area: 'draw', q: 'Move, copy or nudge things', a: 'Drag the selection (it moves as one undo step; attached runs follow). Ctrl-drag leaves a copy. To copy part of a run: select it, click a segment to pick it (Ctrl-click picks more), then Ctrl-drag the picked segment — just those segments are copied as a new run. Arrow keys nudge 50 mm (Shift: 500 mm; on a sheet 1 / 10 mm; in a rack view 1 U). Move / Copy tools take a base point and a target (snaps, typed @dx,dy). Ctrl+C / Ctrl+V pastes in the same place (another level, sheet, tab or project); Ctrl+Shift+V puts its middle at the pointer.' },
	{ area: 'draw', q: 'Rotate or mirror items', a: 'Select what to turn or mirror — shapes of any kind, outlets, racks, blocks, notes — in a plan or on a sheet, then pick Rotate or Mirror (the tool strip beside Move / Copy, or Edit › Rotate / Mirror). Rotate: click the pivot, then a second point: the turn is that point’s angle from +x, as you see it (snaps apply; Shift steps 15°). Or type the angle in degrees: positive turns anticlockwise, so 90 is a quarter turn anticlockwise and -90 clockwise. Mirror: click two points of the mirror line (Shift: 15°, so horizontal / vertical). The originals are replaced by their mirror image; hold Ctrl on the last click to keep them and make a turned / mirrored copy instead. Text is mirrored in place but stays readable; racks, boxes, outlets and blocks keep facing the mirrored way (racks and boxes with door hinges on the other side). Runs ending on what moved follow it. Each is one undo step; locked items are left. In elevations and sections, rotate or mirror in the plan.' },
	{ area: 'draw', q: 'Snap to the grid, to objects, or not at all', a: 'The status bar: SNAP (F9) steps moves and points on the grid — the step beside it is typed in mm (any number: 600 for floor tiles, 44.45 for one rack unit) or picked from the usual ones, OSNAP (F3) snaps to nodes, midpoints, centres, outlets and racks, GRID (F7) draws the grid. Hold Alt while dragging to skip snapping for one action.' },
	{ area: 'draw', q: 'Draw a run (trunk, conduit, wall, line)', a: 'Pick the tool, click each point (or type x,y · @dx,dy · @d<angle · a distance towards the cursor). Shift = 15° steps. Enter or a right-click ends it; C closes it. Trunks / conduits: R = rise / drop, V = a riser to another level; the Location in the tool options sets the height from the level\'s heights. The Z / W / H you type for a tool stay for the session: picking it again brings them back (Z per level). Start or end a trunk / conduit ON another run (a node, a segment\'s middle): they join there — that run gets a node (drag it and both move), and when its height differs the new run drops / rises to it.' },
	{ area: 'draw', q: 'Add a point to a run, or pick one segment', a: 'Select the run, then double-click a segment to add a point there. Click the selected run again to pick the segment under the cursor (Ctrl-click: several). A picked segment of a run with a width (trunk, tray, wall …) has a bar along its edge on the plan: drag it to set the picked segments’ width (10 mm steps, Shift 50 mm, Alt free; zoom in if the run is too thin to show it) — or type W / H in Properties; “as run” goes back to the run’s size. Ctrl-drag a node to branch from it; Alt-drag it to pull it off another run. Drag a run’s node onto a node of another run of the same kind and the two become one run — on a plan only when both are at the same height; runs at different heights are joined in an elevation view.' },
	{ area: 'draw', q: 'Round a run’s corners (bend radius)', a: 'Select the run (a conduit, trunk, tray …): Properties › Size and height › Bend radius sets every corner’s radius (mm; blank = sharp) — the corners are drawn as arcs on the plan. Each corner also has a round grip just inside it: drag it into the bend for a bigger radius, back to the corner for a sharp one (10 mm steps, Shift 50 mm, Alt free) — that corner only. A radius is cut to what fits (half the shorter side). Lengths and routing still measure to the corner.' },
	{ area: 'plans', q: 'How runs (trunks, trays, conduits) are drawn on the plan', a: 'Each run is a band of its real width; runs on the same layer and tier, of the same color, that meet at a point are drawn as ONE outline (their joins merged), its corners slightly rounded and square at the ends, filled faintly in the run’s color (low: blue, high: orange, or the run’s own Color). High runs — in the ceiling — are dashed; a primary run’s outline is stronger. Click a run to select it (the outline itself can’t be picked). A run’s Bend radius rounds its corners further.' },
	{ area: 'draw', q: 'Select several things', a: 'Ctrl-click adds / drops one. Drag a box on empty space: left → right takes what it encloses, right → left what it touches. Ctrl+A takes everything this view shows (in a table, with the table clicked: its shown rows); Edit › Select similar takes everything like the selection.' },
	{ area: 'views', q: 'Find a level, view, sheet, room or rack', a: 'The Navigator window (Ctrl+K puts you in its search box): type part of a name — matching rows show with their parents, and the devices and outlets found under them (an outlet not placed yet opens its plan, selected; “N more” = type more to narrow it). ↑ / ↓ move the highlight, Enter opens it (Ctrl+Enter keeps its tab); the results stay after a click, so a double-click keeps the tab; Esc clears the search. A click opens the row’s view in the active pane; a rack opens its room’s rack view zoomed to it; a sheet unfolds to its viewports, and a click on one opens that view. The open view’s row is marked.' },
	{ area: 'project', q: 'Add or rename a server room or a row of racks', a: 'Window › Racks › + Server room: pick its Floor (the open one first) and type its name — Add room (Enter). In the same list, click a room’s or a row’s name to rename it there (Enter saves, Esc keeps it). Or select a rack: Properties › Room › New server room… or Row › New row… opens a name box under the field (the rack joins it; Enter adds, Esc cancels), and clicking the row’s name under the Row field renames it there. A room has its own Properties: click it in the Navigator, its Properties button in the Racks window, or a rack’s “Room … ›” link — name, code, its rows (+ Row, rename, ▲ ▼ order, containment, ✕), a summary (racks, panels, ports used / free, outlets it serves), Open rack view, Place racks on the plan and Delete room. A row clicked in the Navigator has its own too (name, containment, its racks). Renaming is done in the list, never in the status bar — the amber status bar asks only for a drawing command’s values, and for a name the drawing itself needs: the Rack tool’s new server room, a Leader’s text.' },
	{ area: 'project', q: 'Delete a level, a server room or a section', a: 'In the Navigator, hover (or select) the row: ✎ (or F2, or ⋮ › Rename…) turns its name into a box — type, Enter saves, Esc cancels; ⋮ › Delete… deletes it. A level goes with everything on it; a server room with its racks (and their devices, links, cords) — it asks first when more goes with it, and an empty level or room just goes (the status line says so). A section: click its row (or the cut line on the plan) and press Delete. Undo brings any of them back.' },
	{ area: 'views', q: 'Go back to the view you were in', a: 'The ‹ › buttons at the left of each pane\'s strip, or Alt+← / Alt+→. Each pane keeps its own history.' },
	{ area: 'sheets', q: 'Put a view on a sheet', a: 'In the view, "To sheet…" on its strip: a new sheet or one that\'s there, centred where you\'re looking at a scale that fits. Or on a sheet, the Viewport tool: drag a box — it shows the other pane\'s view (or the last one you looked at), scaled to fit.' },
	{ area: 'sheets', q: 'Put a port grid, a patch schedule or a fill section on a sheet', a: 'Pick a viewport on the sheet; Properties › View lists, besides the plan and elevations, each server room’s racks with patch panels as “… port grid” (the rack’s panels top U down, each port with its number and label as the printed panel sheets draw them; Panel picks one device instead) and each room’s “… patch schedule” (or all rooms): the patch list as a ruled table — every cord’s from and to device, label, rack, U, port, type and length, grouped remove → installed as in the Excel. These are paper: drawn at 1:1 from the window’s top-left, with no scale. A schedule shows the rows that fit its window and ends “… N more cords: from #41”; pick that viewport in another viewport’s Continue from to carry on (it follows when the first grows or shrinks), or type its From cord number. A run’s fill: select it, Properties › Fill, pick the segment and Put on sheet… — its section with the cables packed in (at a true scale), its fill % against the limit, inside size and cables by type. They follow the model, and print in the sheet’s PDF.' },
	{ area: 'racks', q: 'Patch or assign by dragging', a: 'Drag outlets from the Outlets table (the selected ones when you drag one of them) onto a panel port in a rack view: their ports go on from there, pinned — or onto the panel itself: from its first free port. In a rack view the tables panel opens on the Patching tab; pick its Outlets tab first. In Port Properties, drag “Patch … to…” (or “Link to…”) onto the first port on the other device: the cords (cables) go on from there. One undo step each.' },
	{ area: 'views', q: 'Use it on a tablet (touch)', a: 'Two fingers pan and pinch-zoom in any view. With Select, one finger on empty space pans and a tap there clears the selection; one finger on a thing selects or drags it. With a drawing tool, one finger draws (two fingers still pan). Drawing a run or line (trunk, conduit, wall, line): tap each point; Finish and Cancel chips appear in the options row (there is no Enter or Esc), and a double-tap on the last point finishes too. A long press (hold a finger still for half a second) is a right-click: on a thing in the drawing (Select tool) it selects it and opens its menu; on a tab, a Navigator row or a Patching row it opens their menu. Each tab also has ⋮ for its menu. Tabs don’t drag along the strip on a touch screen (the long press is their menu). A finger drags the panel edges, the bar between split views, a window’s title and corner, and the floating tables’ bar and corner, as the mouse does.' },
	{ area: 'racks', q: 'See what a port connects to', a: 'In a rack view, point at a port: a tip shows at once with the port, its full label, the cable plugged in (to which outlet, or which panel) and its patch cords.' },
	{ area: 'views', q: 'Make the floorplan black and white', a: 'Display ▾ › B/W floorplans in a plan’s strip shows floorplans in black and white on YOUR screen, so colored markup stands out (kept in this browser). A sheet has its own: select the sheet › Properties › Display › B/W — that is what its PDF and issues print.' },
	{ area: 'sheets', q: 'Send the PM an issue register', a: 'Tables › Sheets › Issues › ⋯ › Issue register (Excel): every sheet that went out by every issue, with the revision it went at (bold = new in that issue). Issue register, latest only gives one column with each sheet’s last revision.' },
	{ area: 'sheets', q: 'Make a PDF of a sheet', a: 'Open the sheet, then File › Export › PDF of this sheet (or Sheets › PDF of this sheet). Also: right-click it in the Navigator › PDF; or select the sheet (in the Navigator or Tables › Sheets): Properties › Download sheet PDF. Several sheets in one PDF: select them in Tables › Sheets, then PDF (in the table’s order). File › Export › PDF of all sheets prints them all. Sheets print at true scale.' },
	{ area: 'sheets', q: 'Sort and group sheets', a: 'Tables (Ctrl+,) › Sheets: each sheet has a Category (its own, or worked out from its viewports — grey "auto"), Level and Room. Filter with the chips (Active / Archived: click to show or hide each), All or only the Selection, ⋯ › Group by category / level / room / tag, click a header to sort — again to reverse, a third time for the print order; the sort is remembered (# = print order: drag rows to reorder). A group header selects its sheets and Number… numbers them from the category code (RE-01 …). Select several for bulk edits in Properties (one sheet’s Properties › General has its Category, Discipline and Tags too). The category list is shared by every project: Project › Settings… › Sheets. The Navigator’s Sheets ⋮ groups the tree the same ways.' },
	{ area: 'sheets', q: 'Issue a package of sheets', a: 'Tables › Sheets › Packages: select sheets in the register, then + From selection (a fixed list) — or ⋯ › + From chips (a rule — new matching sheets join by themselves). Issue… shows each sheet’s new revision (type another code, or Set all to C01), what changed, sheets added / withdrawn since the package last went out, and a cover page (on by default). In the register, ⋯ › Issue state column shows which sheets changed since their last issue (a State chip filters by it); a sheet’s Properties › Issued in lists every issue it went out in.' },
	{ area: 'draw', q: 'Set where drawing in an elevation goes (work plane)', a: 'With a plan and an elevation of the same level side by side (View › Split), each shows the other’s work plane as a green dashed line. In the plan it is the elevation’s work depth: lines, shapes, images and runs drawn in the elevation go on that line. In the elevation it is the plan’s Z: what you draw in the plan goes at that height. Drag the small green square at the start of the line (Select tool) to move it, in 10 mm steps (Alt: free); its value shows beside it. Double-click the plan’s square to put the depth back to auto (the middle of the floor). Tool options and the band’s “at” box take typed values.' },
	{ area: 'sheets', q: 'Put a picture on a sheet, a plan or an elevation (photo, logo, PDF page)', a: 'Insert › Image…: “From this computer…” uploads a picture or a PDF to the project’s files (Uploads, where Project › Settings… › Files says), or pick one already in Uploads — for a PDF, its page. Then drag its box on a sheet, a plan, an elevation or a section (or click two corners): the picture fits inside, keeping its proportions. In an elevation it stands on that view’s plane at the work depth, and shows only in that view (a photo of a wall, a cabinet’s front). Select it to move it, or drag its grips to resize it: the box always keeps the picture’s proportions (a corner sets the size, an edge changes the other side with it). It prints in PDFs and issues.' },
	{ area: 'draw', q: 'Paste text or a table from Word, Excel or a web page', a: 'Copy text in another app, point at the plan, elevation, section or sheet and press Ctrl+V: a text note appears at the pointer (the middle of the view if the pointer is elsewhere; Edit › Paste does the same), at the Text tool’s size. Cells copied from Excel, or a table copied from Word or a web page, become a markdown table note. Ctrl+C of cad items also leaves their words on the clipboard for other apps — texts and callouts as typed, outlets, racks and labelled shapes by label, one per line — and Ctrl+V back in cad still pastes the items themselves (as long as the clipboard still holds those words).' },
	{ area: 'draw', q: 'Markdown notes and tables', a: 'Select a text and tick Properties › Markdown: # headings, - or * bullets (indent two spaces to nest), 1. numbered lists, **bold**, *italic* and tables — rows like | Item | Qty |, with a | --- | --- | row under the first making it the header (:-- left, :--: centre, --: right). Set the Box width to wrap it; with none, lines and tables keep their natural width. It draws on screen, in PDFs (bold and italic) and DXF (plain TEXT lines and table lines). Double-click to edit the markdown itself.' },
	{ area: 'views', q: 'Paste a screenshot or a picture', a: 'Copy a picture (a screenshot — Win+Shift+S —, an image in a browser), click the plan, elevation, section or sheet it goes on, and press Ctrl+V: the Image tool takes it at once — drag its box where it goes while it uploads to the project’s files (Uploads, named “Pasted <date> <time>”; “Uploading picture…” shows by Saved until it’s done). Esc: leave it out (the file stays in Uploads). The same picture pasted again is the same file — not uploaded twice. Copied cad items paste as before.' },
	{ area: 'project', q: 'Project settings: floors, plans, usages, cable types, labels, sheets, files', a: 'One dialog, Project settings, with a tab list: Floors & heights · Plans & floorplans · Usages · Cable types · Lengths & labels · Sheets (the sheet categories and the title block template) · Files, and Project details… at the bottom of the list. The menu entries open it on their tab: Project › Floors… (Floors & heights), Project › Settings… (Usages), Sheets › Title block… (Sheets); so do the Navigator’s Floors… / Settings… and a sheet’s Title block template… button. Edits save at once, one undo step each (a delete says “— Undo brings it back”: the dialog’s own Undo, bottom right — its tooltip names the step), except the floor range and the name patterns, which wait for Apply floors: changed and not applied, that part is tinted amber with “not applied” (and a dot on the tab), and closing asks “Apply the floor range?” — Apply or Discard (Cancel stays). To add a usage or a cable type, type its code / name first, then Enter or + Add (a usage’s code can’t be changed later; its label can).' },
	{ area: 'project', q: 'Project details (name, codes, client, address)', a: 'Project › Project details…: the projects page’s dialog — the project’s name, description, client and project codes, client, address, logos, your company and its members. Saving changes the project everywhere (the projects list, every tool). It also opens from Project settings (Project details… under its tabs). The sheets’ title block in cad is its own template (Sheets › Title block…: Project settings, tab Sheets) and fills in from these details: the name is its Project field, the client its Client field, the address its Site field (when the template’s Site address is blank), your company its company block (when the template has none), and the author its Drawn field on any sheet whose Drawn is blank (a name or email as initials; with no author, who issued it last). Drawn, Checked and Approved are set per sheet in its Properties — select several sheets to set them on all.' },
	{ area: 'project', q: 'Floors: range, names, heights, numbers, area plans', a: 'Project › Floors… (Project settings, tab Floors & heights): the building’s lowest and top floor (untick the ones that don’t exist) and names from a pattern — these wait for Apply floors (amber “not applied” until then; Apply is greyed when there’s nothing to apply) — and each floor’s heights, saved at once (FFL is stacked from them). No. changes a floor’s number (its area plans follow; a number another floor has is refused, the range widens to take it). Tab Plans & floorplans: each floor’s plan and the floorplan (a calibrated PDF page) it is drawn over — “+ Another page…” when the floor is drawn on several pages, each moved into place with X / Y. + Area plan adds an AREA plan of that floor — a tenant office drawn on its own floorplan (e.g. 33F 3303): same number, heights and FFL, its own plan and floorplans; rename it there, ✕ deletes an empty one at once, and a floorplan’s ✕ removes it — Undo brings either back (an area plan with things on it: the Navigator’s Delete level…, which asks first).' },
	{ area: 'views', q: 'Pan with the wheel and draw by dragging (EOS input)', a: 'The ACAD / EOS button at the right of the status bar picks how the mouse works, for you only. ACAD (the default): the wheel zooms, you click each point. EOS, as in the older EOS tools: the wheel pans (Shift+wheel sideways), Ctrl or Alt + wheel zooms, and a line, a run (trunk, conduit, wall) or a dimension is drawn by pressing at the first point, dragging and releasing at the second; each further press-drag adds a segment, Enter or a right-click finishes. A plain click still works in both. Rectangles, ellipses and boxes draw by dragging in either mode. Right- or middle-drag pans in both.' },
	{ area: 'project', q: 'Upload and set up floorplan PDFs (Uploads)', a: 'File › Uploads… opens the Uploads tool in a window over the drawing: drop or choose PDFs, images, then click a file to see its pages and set the origin, scale, crop, masks and hidden layers. It is the same tool as the /uploads page and writes the same files, so a floorplan changed here shows in the drawing at once. Esc steps back (tool, file, list, close).' },
	{ area: 'project', q: 'Calibrate a floorplan on the plan (origin, scale, crop)', a: 'Project › Floors…, tab Plans & floorplans: each floorplan has Origin · Scale · Crop (amber when the page isn’t calibrated yet — it is then shown as if drawn at 1:100). A PDF just uploaded can be picked at once, uncalibrated, and calibrated here. Origin: click the point that is 0, 0. Scale: click both ends of a distance you know (a grid spacing, a dimension), then type its real length (mm). Crop: click two corners — only that part shows. Esc stops. Project settings steps aside while you click and comes back when it’s done. It is saved in the floorplan’s FILE, as Uploads does, so Uploads and every project using that file change too — when another project uses it, it asks first. It isn’t in Undo: after a change, “Put it back” restores it.' },
	{ area: 'draw', q: 'Add a datum, detail callout or elevation tag', a: 'Blocks panel › Symbol: Datum (level), Detail callout or Elevation tag — pick one and click where it goes (a sheet, a plan or an elevation). They keep their printed size at any scale. Select one to type its words in Properties › Attributes: a datum’s name and height (FFL +3500), a callout’s or tag’s number and the sheet it is drawn on. Turn an elevation tag (Rotation) so its pointer faces what the elevation looks at.' },
	{ area: 'draw', q: 'Put an arrow, dot or tick on a line end', a: 'Select a line (one drawn with the Line tool, on a plan, an elevation or a sheet): Properties › Start / End — None, Arrow, Dot or Tick. Start is its first point; End is its other end (every loose end of a branched line). Several lines at once: select them all. They take the line’s color and print in PDF.' },
	{ area: 'sheets', q: 'Show live values in text (project, level, sheet, counts)', a: 'Type a field in a text, leader or a block’s text: {PROJECT} the project name, {LEVEL} the level it’s on, {SHEET} / {SHEET_TITLE} the sheet’s number / title, {DATE} today, {COUNT:Wireless AP} how many of that block (its name) are placed on the level — inserts and the outlets drawn with it. On a sheet, a note counts what its viewports’ levels hold. The values are filled each time it is drawn (screen, PDF, issues, DXF), so a legend like “APs: {COUNT:Wireless AP}” keeps itself up to date. A field with nothing to show here (no sheet in a plan) stays as typed. Point at Text in Properties for the list.' },
	{ area: 'sheets', q: 'Keep a change history for a sheet', a: 'Select the sheet: Properties › Changes since last issue. Type what changed and who asked for it, then Add (Enter); each note is dated today, and can be edited or removed (×). When the sheet is issued at a new revision, its notes go onto that revision: the Issue panel’s What changed is filled from them (type over it to say something else), the title block’s revision table shows it, and the notes list starts empty again. Point at an issued revision in Properties to see its notes, who asked and who issued it.' },
	{ area: 'draw', q: 'Edit several things at once (Properties)', a: 'Select them (a box, Shift- or Ctrl-click, Ctrl+A): the Properties header says what they are — “3 racks · 5 outlets” — and each kind gets its own folding group (“3 racks”) holding the same groups and fields as one of them. A field they disagree on shows “mixed” (a half-ticked box for a checkbox); a change sets it on every one of that kind, as one undo step. Every field sits in a group (General, Position …): click a group’s title to fold it — it stays folded for every item of that kind in this browser. The layer is in General. Several outlets, racks or sheets also get a folded Renumber group under the header. With nothing selected, Properties shows the open view’s basics: a level’s heights (Floors… edits them) or a sheet’s paper (Select sheet for the rest). Delete is the header’s bin (or the Delete key) for everything — a cord’s Mark for removal is the install workflow’s.' },
	{ area: 'layers', q: 'Delete a block from the library', a: 'Blocks window: point at (or tab to) one of your own blocks and click ✕ — it asks first. It goes from the library for every project and can’t be undone; inserts already placed keep drawing it (their Properties say so). A placed block’s Properties › Block › Blocks window › opens the window. Built-in blocks can’t be deleted.' },
	{ area: 'racks', q: 'Make the same change to more devices', a: 'Change a field of a device (or several) in Properties — its kind, height, ports, maker, a panel’s tier … — several selected at once show their shared fields ("mixed" where they differ), kind included. Or select other devices and press F4: the same change goes on them, one undo step. Its name and U aren’t repeated; a device it won’t fit is skipped and named.' },
	{ area: 'racks', q: 'Add a device from the library', a: 'Window › Device library (it opens with the Device tool): find a template, then DRAG it onto a rack in a rack view — the outline shows where it lands (red: it overlaps or runs off the rack) and the drop adds it, selected. Or click a template, then click a U in a rack.' },
	{ area: 'racks', q: 'Make, edit or delete a device template', a: 'Window › Device library: “+ New” opens a form — name, kind, height (U), ports, port type and numbering, the face it mounts on, width / depth, maker, model — and adds it to the library (★: your own templates; every project sees them). Hover (or tab to) a template: ✎ edits it (every project; devices already placed keep theirs), ✕ deletes it (asks first; can’t be undone). A built-in can’t change — its ⧉ starts a new template from it. Find… also matches the maker and model. To start one from a placed device: select it, then the library’s “+ From <its name>” (or its Properties › Product and size › Save as template…).' },
	{ area: 'plans', q: 'Draw cords along the cable channels', a: 'In a rack view, Display ▾ › Cord channels (in the strip over the view) draws every patch cord down to the channel at the side of its panel, across through the nearest horizontal manager when it changes side, and between racks at mid-height. Off = straight cords. On screen it is yours (kept in this browser); a sheet has its own: Properties › Display › Cord channels.' },
	{ area: 'sheets', q: 'Pick, copy, duplicate and delete several viewports', a: 'Ctrl-click viewport frames to pick more than one (Ctrl-click a picked one to drop it), or drag a window on the empty paper: the viewports it encloses are picked (drag right to left to pick those it touches too). Drag one to move them all; Ctrl-drag leaves the originals and moves copies; arrow keys nudge them; Delete removes them (Undo brings them back; their notes stay on the paper). Ctrl+C / X / V copy, cut and paste them with their views and the notes tied to them — onto another sheet or into another project (a level or room that project lacks shows its plan: use Fit). Ctrl+D duplicates them on the same sheet, a little to one side.' },
	{ area: 'sheets', q: 'Number the viewports, list them, open a viewport’s source view', a: 'Pick a viewport: Properties › View › Number (“1”, “A” …) shows it in a small circle above the window’s top-left corner, on screen and in the PDF. With a sheet (or a viewport) picked, Properties lists the sheet’s viewports — number, label or view, scale: click a row to pick that viewport (Ctrl-click adds it), “Open” opens the view it shows in its own tab, as does “Open source view” in the viewport’s Properties and “Open view” on its chip.' },
	{ area: 'sheets', q: 'Move, resize or pan a viewport', a: 'Click a viewport’s FRAME (its border) on the sheet: drag the frame to move it, a corner to resize it — its edges snap to the paper edge, the margin, the title block and the other viewports, else to a 5 mm grid (Alt: free). Arrow keys nudge it 1 mm (Shift: 10 mm). Properties › Fit centres its view and picks the largest standard scale that fits the window. Its middle doesn’t pick it, so it can’t be dragged by mistake — double-click inside to edit the model in it. The chip on its corner sets its scale and has Pan / zoom content (a drag inside pans its view, the wheel steps its scale). Its view, level and scale are also in Properties. On a touch screen, two fingers inside the viewport being edited (or the picked one, with Pan / zoom content on) pan its view and pinch its scale; it settles on a standard 1:N.' },
	{ area: 'plans', q: 'Send a cable a chosen way (diverse routes, route by hand)', a: 'Select the panel port(s) in a rack view: Port Properties › Route through. Pick a run or riser from “+ through…” and the cable must pass along it; pick more (“+ then…”) and it passes them in that order, from the panel end. Routing takes the shortest way to, between and from them, never doubling back along a run. Change one with its list, × takes it out; with none it is the shortest route. E.g. two backbone cables through different risers for diversity. The length, fill and BOM follow; a run the cable can’t reach (or a dead end it can’t go on from) shows as No route with the reason. A multi-core cable’s cores all go the same way.' },
	{ area: 'draw', q: 'Align or distribute things', a: 'Select two or more things that move (shapes, outlets, racks, texts, blocks …) in a plan, an elevation, a section or on a sheet: Properties shows an Align row — left, centres, right, top, middles, bottom, then distribute across / down with equal gaps (three or more; the first and last stay). They line up as the active view draws them; a group moves as one. One undo step.' },
	{ area: 'plans', q: 'See every cable route on a plan', a: 'Display ▾ › Routes on a plan’s strip draws every cable’s route along the trunks, trays and conduits, in its server room’s color (the key is in the menu, under Routes; rooms sharing a run are drawn side by side). Dashed, lighter lines are ESTIMATED cables: outlet ports not linked to a panel yet (see “Routes and fill before allocation”). Select an outlet to see just its cables’ routes (green dashes; an estimate’s dashes are finer, and shown only when the outlet’s server room is set on its ports).' },
	{ area: 'plans', q: 'Routes and fill before allocation (estimated cables)', a: 'Every outlet port with no link yet gets an estimated cable to its server room, routed as a link would be: onto the nearest run of its tier within 10 m that serves that room, along the runs, to the room’s patch frames (every rack in the room when none is marked; the centre of the room’s outline when no rack is placed). The room is the port’s own, else another port’s of the same outlet, else the one most of its zone’s ports go to, else the level’s only server room, else the room the nearest run serves. Display ▾ › Routes draws them dashed and lighter; fill counts them — Properties › Fill says e.g. “12 × cat6a (4 estimated)” and “12 cables · 4 estimated”, the plan’s Fill bands “35% · 4 est.”. When a port is allocated (linked), its estimate goes and the real route takes its place. Selecting an outlet whose server room is set (on its port or ports) highlights its estimated routes in finer green dashes; a room guessed from the zone, level or nearest run is not shown that way. The Bill of materials and the Cable schedule count estimates too, marked “estimated”, so totals before allocation are usable (the BOM line “… — estimated, not allocated yet”; the schedule’s italic rows after the real cables, with “+ N estimated … m” beside the totals and a Status column in Excel); estimates are always to buy, and a linked port’s goes. Outlets of usage N/A and outlets not placed get none.' },
	{ area: 'plans', q: 'Which server rooms a run serves (an outlet says “no run … serving its room”)', a: 'Select the trunk, conduit or tray: Properties › General › Serves — a box per server room on its level(s). A cable joins a run only where the run serves the cable’s server room (from its outlet, and at its rack); none ticked = every room. Tick a room to let its outlets and racks use the run. Once a cable is in the containment it goes along any run, so risers need nothing set.' },
	{ area: 'plans', q: 'The riser view: floors, EPS rooms, high / low, cable groups', a: 'Riser on a building view’s strip. With nothing selected, Properties › Riser view › Floors lowest – top picks the floors it shows — a project setting, for everyone (every riser view and its sheet viewports show the same); Display ▾ › Hide empty floors (your view only) squeezes floors with no server room. Each riser shows its tier (HIGH / LOW) on its label and an EPS box on every floor it passes (named after an EPS space drawn round it there). Backbone cables to the same two racks of one type are one line: it runs in the ceiling plenum where its route takes high runs on that floor, in the floor void for low runs. Click a line: Properties › Backbone sets its Riser label and color (By layer = by cable type: fibre amber, copper blue). To make a riser reach another floor: select it, Properties › Riser › Reaches.' },
	{ area: 'racks', q: 'Link panels with a multi-core cable (24-core fibre)', a: 'Project › Settings…, tab Cable types: give the type its Cores (e.g. 24). Then select the ports on one panel, Port Properties › Link to…, pick that type as Link type and click the first port on the other panel: the ports go, in order, into cables of that many cores (48 ports → 2 cables). Fill, the BOM, the cable schedule, the cable list and the riser view count each cable once; the Links table shows each core (“core 3 of 24”), and a type, status, riser or length change goes to all its cores.' },
	{ area: 'racks', q: 'Link several panels to a switch (four 24-port panels → a 96-port switch)', a: 'In a rack view select the panels (click the top one, Shift-click the bottom one). Properties › Link N panels to… (or press L), then click the switch’s first port: all their ports go on in order, the top panel first — 1–24, 25–48 … A port that already has a cable is skipped. Before anything is made, a list shows each cable (port → port) and what is skipped: Link N (Enter) makes them as one undo step, Cancel (Esc) none — as for Patch to…. That click finishes it and your tool comes back (Esc cancels). A panel port cabled to a switch shows the switch’s port number (01–96), or the switch port’s own label if it has one; set the switch’s Kind to switch.' },
	{ area: 'racks', q: 'Number a switch’s ports down (2 under 1)', a: 'Select the device: Properties › Ports and labels › Numbering. Across (2 beside 1) is how patch panels count: 1–24 on the top row, 25–48 under. Down (2 under 1) is how most switches count: 1 over 2, 3 over 4 …, down each U’s pair of rows — a 96-port 2U switch (Arista CCS-720XP-96) has 1–48 on its top two rows and 49 under 2. Several devices at once: select them all. Only where the ports are drawn changes; cables stay on the same port numbers.' },
	{ area: 'racks', q: 'Find the middle of a panel’s or switch’s ports', a: 'A device with 24 ports or more has a small tick on its bottom edge under the middle of its ports, in the rack elevation. Cable a frame’s left-hand outlets to the switch ports left of the tick and its right-hand ones to the right.' },
	{ area: 'plans', q: 'Put several runs at their heights at once', a: 'Select the runs (Ctrl-click, a window, or Ctrl+A on the plan): Properties › Location sets every one to under floor / ceiling plenum / below ceiling / on wall, from its own level’s heights. “Each by its tier” sends high runs to the ceiling plenum and low runs under the floor in one step — for a mix put at one height (an import). One undo step.' },
	{ area: 'sheets', q: 'Print sheets in black and white', a: 'File › Export › Monochrome PDFs (a tick; kept in this browser): every sheet PDF then prints lines and text black, fills light grey and floorplans / pictures grey — for cheap prints. The file name ends “(mono)”.' },
	{ area: 'views', q: 'Copy the view as a picture', a: 'View › Copy view as picture puts the active view, as you see it (its zoom, its floorplan), on the clipboard as a PNG — paste it into an email or a report.' },
	{ area: 'project', q: 'Photo surveys', a: 'File › Photo surveys… opens this project’s photo surveys in a new tab (the survey tool).' },
	{ area: 'plans', q: 'Set a run’s inside size for fill', a: 'Fill (the % per segment, the 40 % check) is worked out against the run’s INSIDE size: by default its outside size less a 3 mm wall each side (as the old Fill rate tool did). Select the run: Properties › Size and height › Inside — type the real inside width × height (a conduit: its inside Ø); clear a box to go back to the 3 mm wall.' },
	{ area: 'plans', q: 'Add cables to a run by hand (power, coax, or before routing)', a: 'Select the run (trunk, tray, conduit): Properties › Cables by hand › Add cables. Set how many, the type (a cable type from Settings, or any name such as power), its outer Ø if it isn’t the type’s, and where: the whole run or one segment (pick the segment first and Add puts the row on it). Fill — the % per segment, the section picture and Display ▾ › Fill on the plan — adds them to the routed cables; the list marks them “by hand”. Each edit is one undo step.' },
	{ area: 'project', q: 'Choose where issue PDFs and logos are stored', a: 'Project › Settings…, tab Files: new uploads go to UploadThing (the default) or Firebase Storage, for everyone on the project. Files already uploaded stay where they are; Uploads lists both kinds.' },
	{ area: 'draw', q: 'Draw an arc', a: 'Shape tool › Shape: Arc (3 points). Click where it starts, a point it passes through, then where it ends (Esc cancels). On a plan, an elevation or a sheet, like the other shapes. Select it: grips on its start, middle and end — drag one and the arc goes through the other two (Shift on an end: 15° steps from the other end).' },
	{ area: 'draw', q: 'Edit a dimension (its points, line, text, extension lines)', a: 'Select it: grips on its two measured points (move them; Shift = 15° steps), the middle of its line (nearer / further), its text (drag it anywhere) and each extension line’s start (slide it to set the gap from the point). Properties: what it measures, its own text (blank = the length) and — once the grips moved them — Reset handles. The length shows in mm up to 10 m, then in m.' },
	{ area: 'draw', q: 'Annotate one elevation or section', a: 'In an elevation or a section, Text, Leader, Cloud, Dimension, Line and flat shapes (Shape tool) are drawn on that view’s plane and belong to it: they show in that view (and its viewports on sheets) only, not on the plan or the other elevations. Trunks, conduits, walls and boxes with a depth are part of the model and show everywhere.' },
	{ area: 'layers', q: 'Place a block (a faceplate, a symbol, your own)', a: 'In the Blocks list: click a block, then click where it goes (it stays on for the next one; Esc stops) — or drag the block from the list onto a plan, an elevation, a section or a sheet and let go where it goes (its ghost follows; the tool you had comes back). In an elevation or section it goes on the wall behind the drop, at that height.' },
	{ area: 'views', q: 'What a plan shows in elevations', a: 'Elevations and sections show the model: walls, racks, trunks, conduits, boxes with a height and lines that rise. What is drawn or placed on a plan stays on the plan: outlets, blocks and symbols, text, dimensions, flat shapes and flat lines. To show an outlet in elevations, place it in an elevation with the Outlet tool (on the work plane) at the clicked height: it then shows in every elevation and section that sees it, and on the plan. A block (a wall faceplate) placed from the Blocks list in an elevation goes on the wall behind the click and shows ONLY in that elevation — not on the plan or in other views. Or select outlets or blocks already placed on the plan and tick Properties › Elevations “show in elevations” (untick for plan only); they show at their Height (Z). A block is one drawing, drawn the same in every view: a faceplate is the plate, its frame and its sockets (power: prongs and earth; data: an RJ45), at real size, on a plan as in an elevation — as the Blocks window shows it.' },
	{ area: 'draw', q: 'Link a symbol to a sheet or a web page', a: 'Select a placed block (an insert) and open Properties › Link: “A sheet” picks one of the sheets, “A web page” takes an address (http, https or mailto; “example.com/specs” gets https://). Each marker has its own target, not the block. Pointing at it with the Select tool shows a small badge (“↗ A-101 …”); a double-click opens it — a sheet in a tab, a web page in a new browser tab. Open in Properties does the same.' },
	{ area: 'draw', q: 'Make a block in an elevation', a: 'Draw it in an elevation or section with the drawing tools (lines, boxes, circles, text), select those shapes and press Make block… in Properties: they become a new global block, at real size, and one insert replaces them there (it shows only in that elevation). A block is one drawing, drawn the same wherever it is placed: from the Blocks window, in an elevation it shows only there, and on a plan only on the plan (unless you tick “show in elevations”, then it shows at the insert’s Z).' },
	{ area: 'layers', q: 'Make a block from shapes drawn on a sheet', a: 'Select the shapes on a sheet and press Make block… in Properties. Shapes drawn inside a viewport (tied to it) are in that view’s mm: the block is in model mm and the insert stays in the viewport. Shapes drawn on the bare paper are in paper mm: the block is made at model size by the sheet’s first viewport scale (the message says which; with no viewport it stays paper size) and the insert on the paper shows it at the same size. The block is global, so use it anywhere: in a viewport, a plan or a model. Pick shapes from one place (one viewport, or all untied) — mixed ones are refused.' },
	{ area: 'sheets', q: 'Annotate a viewport on a sheet', a: 'With the viewport NOT being edited, use Text, Leader, Cloud, Dimension, Line or Insert where it shows: what you draw is tied to that viewport (it moves and scales with it) and stays on this sheet. Started on the paper, it belongs to the paper. Dimension and Leader points snap (OSNAP) to what the viewport shows under the pointer — outlets, racks, run nodes, shape centres — Alt or OSNAP off turns it off; elsewhere on the paper they round to 0.5 mm. Annotation tools never write into the model from a sheet — used inside a viewport you are editing, they leave it first.' },
	{ area: 'draw', q: 'Copy one shape’s look onto others (Match properties)', a: 'Select the shape to copy from, then Edit › Match properties (or right-click it › Match properties…). Click each shape that should look the same: it takes the source’s layer, color, fill, line type and lineweight, and a text takes its size too. Each click is one undo step. Esc or right-click ends it. With nothing selected, the first click picks the source.' },
	{ area: 'views', q: 'Work with the drawing tabs', a: 'A tab over the drawing is each view or sheet you’ve opened. Click one to show it in the active pane; drag it along the strip to move it (a blue line shows where it goes). Double-click a tab in italics (a preview) to keep it. × or a middle-click closes it; a right-click (or ⋮ on the active tab — on a touch screen every tab has one) has close others / to the right, show in the other pane and To sheet; ⌄ lists every tab.' },
	{ area: 'views', q: 'Put two levels side by side (2F beside 3F, area plan 3303 beside 3307)', a: 'View › Split (or the two-column button) shows two panes; each has its own view AND its own level. Click in a pane to work in it, then pick a level or view in the Navigator (or a tab): only that pane changes. The open level everywhere else — Properties, the tools, the Outlets table, Floors, Project › Rename this level… — is the active pane’s. Each pane’s tab keeps its own Back / Forward, and a refresh (or a copied link) opens both panes on their levels. Undo / Redo of something on the other pane’s level makes that pane the active one (this pane stays as it is).' },
	{ area: 'racks', q: 'Select a run of devices in a rack, and unlink them', a: 'In a rack view, click a device (its body or a port), then Shift-click another in the same rack: every device between them on this face is selected (Ctrl-click adds or drops one; a box works too). Properties then has Remove links (N) — the outlet links, ties and backbone on all their ports — and Remove cords (N). Both act at once as one undo step (“— Undo brings them back”), as on selected ports. One device has the same buttons.' },
	{ area: 'racks', q: 'Move outlets from one panel to another', a: 'Pick outlets in the Outlets table (or on the plan): a rack view shows the panel ports they’re on in blue. To move them: in a rack view pick the ports (click one, Shift-click the last), then press on one of the picked ports and drag it onto the first port of another panel (or onto the panel: its first free port). Their outlets go onto the free ports from there, pinned; ports with a patch cord stay (take the cord off first). Ctrl+Z undoes. Dragging a panel by its body, or by a port that isn’t picked, still moves the panel.' },
	{ area: 'racks', q: 'A panel port shows the wrong outlet number', a: 'A panel port shows the outlet PORT’s label. Renaming or renumbering an outlet updates its port labels only where they contain the old label — imported outlets can have port labels in another form (outlet 245 with ports 056.A), which then stay. Select the outlets (in the Outlets table or on the plan): Properties says when their port labels don’t match, and Ports from label labels those ports from the outlet’s label again (245.A, 245.B). Ports that contain the label are left alone; it asks first if a printed panel changes; Undo puts them back.' },
	{ area: 'racks', q: 'Give half a panel its own label', a: 'Select the panel; in Properties › Ports and labels, Split labels › In two makes a top and a bottom range. A range with an empty label is named from its cables — this rack and the rack they go to (P3A-R301, P3A-R302), else the panel’s name -A / -B — and follows them, so you can split before or after linking. Type a label to set your own; clear it to go back. Edit a range’s first / last port there, + Range adds one, ✕ removes one. A port in a range is labelled “label:NN”, counted from the range’s first port (the 25th port of a panel whose bottom half is P3A-R302 is P3A-R302:01), and the port at the other end of its cable shows the same label. A port linked to an outlet keeps the outlet’s label. The rack view shows each range’s label over its first port.' },
	{ area: 'racks', q: 'Change the order of racks in a rack view or a row', a: 'The order comes from the plan: a row’s racks run left to right as seen from their front (the side without the thick back line) — move or turn them on the plan to change it. A row that turns a corner is read run by run, in the way its widest racks face; racks not on the plan come last. Where the plan order is wrong (racks or managers at right angles): Window › Racks, drag a rack up or down its row (by its ⠿, or anywhere on it) — up the list is left in the rack view; a rack moves only within its own row. The order is kept for that row (allocation fills in it too; a rack added later goes after), and “↺ plan order” on the row puts it back. The rear view shows the same racks right to left.' },
	{ area: 'layers', q: 'Which layer did that go on?', a: 'The Layer chip above the drawing shows the layer new lines, boxes, circles, text and blocks go on (“by kind” = Drawing, with walls on Walls and trunks on Trunks); pick another there, or click a layer’s name in Layers, to draw on it next. A note at the bottom of the drawing names the layer only when the shapes went somewhere other than the chip’s layer. Pasted and copied items keep their own layers.' },
	{ area: 'layers', q: 'Give a layer a color', a: 'Layers: click the color swatch at the start of a layer’s row — the same color grid as in Properties (plus Custom). Its items draw in it unless they have their own color. By layer in the grid (or a right-click on the swatch) goes back to the default: a round dot shows the color its items draw in anyway, a square a color set on the layer. Undo puts it back.' },
	{ area: 'draw', q: 'Turn a rectangle, box or ellipse', a: 'Select it: Properties › Position › Rotation (°) turns it about its centre, clockwise (15° steps with the arrows; type any angle). Several at once: select them all — each turns about its own centre. Racks and blocks have their own Rotation (°) too.' },
	{ area: 'layers', q: 'Give a layer a line type or lineweight (By layer)', a: 'Layers: click the small line sample on a layer’s row, then pick its line type (Solid, Dashed, Dotted, Dash-dot) and lineweight (mm on paper). Lines, boxes and circles on that layer take them unless they set their own in Properties (Line type / Lineweight: “By layer” there means the layer’s). Text and trunk widths don’t change. It shows on screen and prints in PDF; DXF gets the line type. Undo puts it back.' },
	{ area: 'draw', q: 'Draw a floor-tile grid on a box', a: 'Select a box (a rectangle region on a plan): Properties › Box › Floor tiles. It lines the box every Tile size mm (600 to start; type any size, as for the grid step), from the box’s top-left corner — Offset X / Offset Y slide the first lines so the grid meets the real floor’s tiles (only the remainder of the tile size matters). A turned box turns its tiles. The lines show on screen, in PDF and on their own DXF layer (A-FLOR-TILE). A grid too fine for the box’s size (over 300 lines across) isn’t drawn.' },
	{ area: 'layers', q: 'Set the color, line type and lineweight new shapes start with', a: 'Project › Settings…, tab Drawing style: Color (By layer = as before), Line type and Lineweight. A new line, box, circle, ellipse, polygon or arc is made with them (shapes already drawn don’t change; Properties changes any shape). A layer that sets its own color, line type or lineweight still rules that one: the project default fills only what the layer leaves alone. In the DXF export a lineweight is written as the entity’s own (the nearest standard DXF weight) and a filled box or circle comes as a solid hatch of its fill color.' },
	{ area: 'layers', q: 'Layer presets, groups and changing several layers at once', a: 'Layers › Presets…: the + saves the layers shown now under a name (for you, in this project, in this browser); pick one to show exactly that set again; the bin deletes the picked preset. With viewports picked, a preset sets their layers instead (and + saves the first one’s). Groups: a layer named “IDF1/Outlets” sits under an IDF1 heading, and the heading’s eye hides or shows all of its layers. Ctrl-click layer names to pick several (Shift-click: a range): the eye, lock, color and line type / lineweight then change all of them (the project-level ones as one undo step), and Group… files the picked layers under a heading you name (“-” takes them out). A plain click on a name clears the picks and makes it the current layer.' },
	{ area: 'layers', q: 'Hide a layer in a viewport', a: 'Each viewport has its own layers, apart from the model: pick the viewport (or edit inside it) and the eyes in Layers are that viewport’s — click one to hide or show the layer there (Shift: every viewport on the sheet; a group’s eye and several picked layers work too). With several viewports picked (Ctrl-click, or a window round them), one eye sets them all; a faint eye means shown in some of them, and a click shows it in all. Layers none of the picked viewports draws anything on fold under “Not in these views” at the end, where they can still be set. It’s stored on the sheet: it prints, and everyone sees it. On a sheet with no viewport picked, the eyes are the sheet’s own: they hide layers among its paper notes and legends (stored too). Everything on a sheet prints exactly as it shows. In a plan, elevation or other model view, the eye is your own (this browser) and doesn’t reach sheets. A new layer starts hidden in the viewports that already exist (made with + Layer, pasted in, or imported), so finished sheets don’t change; show it per viewport. Notes follow the same rules: a note on a hidden layer (for a note tied to a viewport: hidden in that viewport) disappears, and a note set to By layer takes its layer’s color.' },
	{ area: 'views', q: 'Open, move and dock windows', a: 'Window menu: tick a window to open it. Drag a window by its title to float it over the drawing; drop it on the left or right edge to dock it there. The tables under the drawing (Outlets, Patching, Sheets, Links): ✕ closes them to their bar of tabs — click a tab (or Ctrl+,) to open them on it. Ctrl+. hides every window and brings them back; Window › Reset layout puts everything back. The Blocks and Device library windows step aside in a view where their tool can’t work (a rack view, a sheet) and come back with the plan; the Window menu shows them unticked meanwhile.' },
	{ area: 'racks', q: 'Pick ports, or move a device, in a rack view', a: 'Click a port to pick it; Shift-click another for the range between, Ctrl-click to add or drop one — or press on a port and DRAG across the others: the pick runs from the first to the one under the pointer. To move a device, drag it by its body (the edge beside its ports, or its name strip), or Alt-drag from a port; it moves by whole U, into another rack when dropped on one (Ctrl: a copy). Shift-click another device of the same rack picks the devices between.' },
	{ area: 'racks', q: 'Patch ports in a rack view', a: 'Open the room\'s rack view (Racks › Rack view). Pick the Cord tool, click a port, then the port it goes to. Several ports: select them (Shift-click a range), press P (or right-click them › Patch to…, or the blue Patch to… at the top of Properties), then click the first target port. A whole device: select it and press P (or Properties › Ports and labels › Patch all … ports to…). Before anything is made, a list shows each cord (port → port) and how many ports are skipped and why: OK (Enter) makes them in one undo step, Cancel (Esc) makes none. In step (the default) the ports go port for port from the one clicked, a pair skipped when either port is taken, stopping at the other device’s last port; tick Fill free ports only to pass over its taken ports instead (it stays as last chosen; Ctrl on the click picks the other way that time).' },
	{ area: 'racks', q: 'How many ports of a device are used or free', a: 'Select the device: Properties › Ports and labels reads “24 ports · used 20 (patched 12, linked 18) · free 4” — patched = a patch cord in the port, linked = a permanent cable (to an outlet, a tie, backbone), used = either, free = neither (a cord marked for removal no longer counts). The port tip in a rack view ends with the device’s count, and a rack’s name in the Racks list shows its devices’ total in its tooltip.' },
	{ area: 'racks', q: 'Re-patch a cord, or start one from a port', a: 'Select a cord in a rack view: grips show on its two ends — drag one onto another port to move that end there (a taken or unlabelled port says why it refuses; Ctrl+Z undoes). Select a port with no cord: a small + shows at its top-right corner. On a panel port with a link (an outlet, a tie) it starts a patch cord — click the port it goes to; on a panel port with no link it starts a link (Link to…); on a switch it starts a patch. Esc cancels. A port with a cord in has a green edge, and in the Outlets table its panel port (Panel column) reads green — hover it for where the cord goes. A cord’s Length in Properties takes any length you type (the standard ones are offered); a typed length is locked — untick lock to go back to the estimate from the racks.' },
	{ area: 'racks', q: 'Cord status: add, change, replace, remove, installed', a: 'A new cord is ADD (to install). Moving an end of an INSTALLED cord makes it CHANGE, remembering where it was (Properties: “Was: …”); moving it back onto those ends makes it installed again. Deleting an installed cord (Delete, or Remove cords on a device or ports) only marks it REMOVE — it still has to come out on site — and a change being removed comes out from its old ends; a planned (add) cord is simply deleted. Installed (Properties) = done on site; on a remove cord it reads Removed on site and the record goes. Revert goes back to the old ends and status. The status box sets any status by hand to fix a mistake (it never deletes). REPLACE (set by hand, in the status box or the Patching tab’s Status cell) tells the installer to swap the cord for another at the same ends: set it first, then the new type, color or length — Properties and the list (↶ by the type) say what it replaces, and the schedule has a REPLACE group with “was …” in Was From; Revert or Mark for removal bring the old cord back, Installed confirms the new one. Deleting a device or rack takes its cords with it — the confirm says how many were installed, so export the changes first if the installer needs them.' },
	{ area: 'racks', q: 'Record the cords of a built site (Surveying)', a: 'New cords: Planning · Surveying — in the Patching tab’s bar, the Cord tool\'s option bar and Project › Settings › Cable types. Planning (the default): a new cord is ADD, to install. Surveying, for recording what is already on site: new cords — one at a time, Patch to… on several ports, or the + on a port — are INSTALLED at once (the status line says so). It is a project setting: everyone on the project records the same way until it is switched back (“for everyone” beside the toggle says so).' },
	{ area: 'racks', q: 'Record the patch cords bought (label batches)', a: 'Patching tab › ⋯ › Cord labels… (or Cabling › Cord label batches…) › + Batch: a row per batch of cords bought with pre-printed labels — its type, length and color, its first and last label as printed (2AR-0001 … 2AR-0100: the same text before a number that counts up), how many were ordered (blank = the labels in the range) and delivered. Each batch shows how many of its labels the cords’ Cord IDs use, how many are free and the next free one. Below, per type · length · color: the cords, the labels ordered and delivered, how many cords are still short of a label, and the label the next order continues from. A cord carrying a label from a batch of another type, length or color is listed. + Batch starts from a kind that is short, at its next label. Undo takes back each edit.' },
	{ area: 'racks', q: 'Export the patch schedule (all, a room, the changes)', a: 'Patching tab › Patch schedule · cord BOM… (or File › Export › Patch schedule · cord BOM…). Pick which cords: All rooms — one Excel sheet per server room — or one room, or the list\'s selected rows, or the rows it shows (its scope, status chips and Find). Tick “changes only” for just the work (add / change / remove) — e.g. all rooms + changes only = every changed patch. Each sheet lists the cords in work order (remove → change → add → installed), and inside each group by “sort by” (From label by default, or From rack / U / port, To label, cord ID). Each end has Device, Label, Rack, U, Face, Port; then type, length, Cord ID, status, notes, Was From / Was To and a hidden Key. A Bill of Materials sheet counts them by type × length. The dialog shows that count before you export. The installer\'s returned file can fill in cord IDs: ⋯ › Import cord IDs… (every room sheet is read).' },
	{ area: 'racks', q: 'Import cord IDs from a returned patch schedule', a: 'Patching tab › ⋯ › Import cord IDs… reads an Excel the installer filled in: on every sheet (except Bill of Materials), row 1 is the header; the IDs go in the column headed “Cord ID” (any position), and each row is matched to its cord by the hidden “Key” column — so export the schedule from here, fill in Cord ID, and keep Key (rows can be re-sorted or deleted; blank and “-” are skipped). It asks before setting them, and Undo puts them back. A file with no Key column is matched by “#” only if it has one sheet and the cords haven\'t changed since.' },
	{ area: 'racks', q: 'Bill of materials: what to buy, a rack BOM for some rooms', a: 'File › Export › Bill of materials… (or Cabling › Schedules) shows it before Excel. Materials is what to buy for the whole project: outlets and jacks, racks, panels and devices, cable by type (routed lengths + waste, in boxes; estimated cables of ports not linked yet on lines of their own, marked “estimated”), patch cords, containment, core drills — cables already installed and cords already in place aren’t counted (only cords to add or replace). Rack BOM lists racks, VCMs and their containment accessories by SKU, all racks together or row by row; with racks in several rooms, tick the rooms it is for — grouped by level, any levels, all at first (a level’s box ticks its rooms). A rack or device with no catalogue product is listed by its maker and model (else its kind and size). Export to Excel writes what is shown.' },
	{ area: 'racks', q: 'Port map: a drawing of switches and panels', a: 'Select the panels or switches in a rack view (or their rack), then Cabling › Port map view of the selected devices. It opens as a view: each device drawn like its faceplate, the ports where they are on it (a 48-port 1U = 2 rows of 24), every port with its number small in the top-left corner and the label of what is at its far end — the outlet a switch port reaches through its cord and panel, the switch port a panel port is patched to (unpatched: the outlet its cable goes to). It follows the model as cords change. To sheet… puts it on a sheet (at 1:1, 24 ports ≈ 290 mm: an A3 landscape); Excel (VLAN) in its strip exports the same ports as a list.' },
	{ area: 'racks', q: 'Port map: the Excel for VLANs (network engineers)', a: 'Select the panels or switches in a rack view (or their rack), then File › Export (or Cabling › Schedules) › Port map of the selected devices (Excel, VLAN) — or Excel (VLAN) in a port map view. The Excel lists every port, device by device: room, rack, U, port, device, its label, the outlet(s) at the ends of its circuit and where they are, the port its cord goes to (Patched To), any device port beyond (Far End), the cord ID and status (add = planned) — and an empty, highlighted VLAN column for the network engineer to fill in. Cords marked remove are left out.' },
	{ area: 'views', q: 'The tables’ bar: find, filter, act on the selection', a: 'Each table (Outlets, Patching, Sheets, Links) has one bar, laid out the same: which rows (this view, the Selection, or All), Find, the filter chips (click one to show / hide those rows), the count — then, once rows are selected, what acts on them (Allocate, Assign → port…, Installed / Remove …, PDF, Issue…, Archive, Delete …; without a selection a hint says what to select) — and ⋯ at the right for the exports and rarer actions (whole-level allocation, cord labels, import cord IDs, Purge removed, the issue register, Group by …).' },
	{ area: 'views', q: 'Edit cells in the tables', a:'Every table works the same way. A click selects a row (and the item on the drawing — Properties shows it; an outlet, cord or link off the screen is panned into view, Shift+Home zooms to it); Shift-click selects a range, Ctrl-click adds or drops one. Double-click a cell to edit it, or press F2 / Enter to edit the selected row’s first editable cell. In the box, Enter saves and goes to the same cell on the next row (Shift+Enter: the row above), Tab / Shift+Tab to the next / previous cell, Esc cancels, clicking away saves. Not editing, ↑ / ↓ move the selection and Ctrl+C copies the rows shown for Excel. Editable: Outlets — label (its ports follow), usage, tier, server room; Patching — cord ID, status, notes; Sheets — number, title, category, discipline, tags (double-click elsewhere on a sheet row opens the sheet); Links — cable type, status.' },
	{ area: 'racks', q: 'Edit cord IDs, status and notes in the patch list', a: 'Double-click a Cord ID, Status or Notes cell in the Patching tab (or select the row and press F2). Enter saves and goes to the same cell on the next row (Shift+Enter: the row above) — for typing a run of cord IDs; Tab / Shift+Tab: the next / previous cell (Cord ID → Status → Notes → the next row); Esc cancels; clicking away saves. A status set here follows the install rules (installed / add clear the history; remove keeps it).' },
	{ area: 'racks', q: 'Mark cords installed, restore or remove several at once', a: 'In the Patching tab, select cords (click, Shift-click a range, Ctrl-click to add or drop one, Ctrl+A for every shown row). The bar over the list then has Installed · Add · Remove · Restore · Delete, each with how many cords it changes, and Type / Color for all of them (a type brings its color; the status stays). Right-click the rows for the same, and several cords selected in a rack view show them in Properties. Installed on a cord marked for removal means it is out — its record goes. Delete takes the records outright with no removal work; Remove follows the status rules. Each acts at once and the status line says what changed — Undo brings it back. ⋯ › Purge removed (N): every cord marked for removal in the list\'s scope is out on site. It asks first (how many cords go; their records can’t be brought back by the installer’s list), then it is one undo step. Rows marked for removal are struck through; ↶ by an end of a CHANGE shows where it was (hover it).' },
	{ area: 'plans', q: 'Allocate outlets to panel ports', a: 'Select outlets in the Outlets table (or on the plan): the table’s bar shows Allocate N — each port gets a panel port of its server room, racks in row order, top U down — and Re-allocate…, Assign N → port… (by hand, pinned) and Find/replace…. ⋯ › Allocate this level / Re-allocate this level… do every outlet on the level; ⋯ › Re-allocate pinned links too includes the hand-placed links. A panel port with a label of its own (UPLINK-1) or in a labelled range of ports is left free by Allocate and Assign — the issues list names them. Filling free ports happens at once (Undo brings it back); it asks first only when existing links would move.' },
	{ area: 'racks', q: 'Print panels with their labels', a: 'Racks window: a room\'s ⋯ → "Print panels with labels (PDF)…" (or "Export panel labels (Excel)…"). Afterwards it offers to mark the panels as printed, so later label changes ask first.' },
	{ area: 'racks', q: 'Give a server room its own floor and ceiling (rack views)', a: 'In a rack view, drag the floor line (FFL until the room has its own) or the ceiling line up or down — 10 mm steps, Shift 50, Alt free; dropping the floor back on FFL clears it. Or select the room (the Navigator, the Racks window’s Properties, or a rack’s “Room … ›” link): Properties › Floor and ceiling — Floor (FL + mm, − = below FFL) and Ceiling (blank = the level’s). They are the room’s, for all its racks: the racks stand on its floor — in rack views, elevations and cable heights — and the rack view draws its floor and ceiling lines (its ceiling instead of the level’s) with the slab lines. In a rack view, Display ▾ › Room lines and Other face show or hide those lines and the faint devices on the other face; they are layers too (Room lines, Other face), so a sheet’s viewport can freeze them.' },
	{ area: 'plans', q: 'An outlet’s zone and server room', a: 'Outlet Properties › Zone (the level’s zones; New zone… adds one) and Server room (every port). The Outlet tool’s bar sets them for the next outlets (Zone, Server room — “as last” = like the last one placed); the first outlet on a level takes the level’s server room when it has just one.' },
	{ area: 'plans', q: 'Usage colors and outlet tips', a: 'Outlets on a plan are drawn in their usage’s color (Project › Settings…, tab Usages; their labels stay as they are) — or by their layer’s color: Display ▾ › Usage colors on a plan’s strip switches it on your screen; a sheet has its own (Properties › Display › Usage colors), which its PDF prints; and a patch panel’s ports cabled to outlets get a light tint of that color in rack views — on screen and in PDFs. Point at an outlet on a plan (Select tool) for an instant tip: its label, usage · tier · mount, and each port with the panel port it’s on.' },
	{ area: 'plans', q: 'Ctrl+K in cad and the app-wide search', a: 'Inside cad, Ctrl+K is cad’s own Find (levels, views, sheets, rooms …); the app-wide palette no longer opens on top of it. A level or sheet picked in that palette from the title bar opens in a tab of the cad page you are on, without reloading it.' },
	{ area: 'plans', q: 'Set an outlet’s usage (desk, AP, printer …)', a: 'Outlet Properties › Usage: one button per usage of the project’s list (Project › Settings…, tab Usages), in its color — click one; the picked one is filled. “—” = none (nothing drawn under the symbol). With several outlets selected, the click sets them all (none is filled while they differ). The Outlet tool’s bar and the Outlets table keep a list.' },
	{ area: 'racks', q: 'Export frame label sheets (Excel, like the Frames tool)', a: 'Whole level: File › Export › “Frame label sheets — this level / all levels (Excel)” (a sheet per frame, every server room), and “Panel labels — this level / all levels (Excel)” for the label printer (then the “Mark printed” offer) — the same four are in the Racks window’s room ⋯ menu. One room: Racks window: a room’s ⋯ → “Frame label sheets (Excel), a sheet per frame” or “…, one sheet for the room”. Each rack is drawn as RU rows (two Excel rows a U) × 24 port columns: every port its label, colored by the usage of the outlet it goes to; ports reserved for a usage in that color with a dotted border; switches, managers and other devices as one block. On one sheet the racks stand side by side with their bottoms lined up. Pages are A3 landscape fitted to one page, with the file name and page number in the footer. The room’s patch frames are exported (every rack holding a panel when none is marked).' },
	{ area: 'draw', q: 'Undo a mistake', a: 'Ctrl+Z (Edit › Undo). Undo selects what came back or changed and opens its level.' },
	{ area: 'project', q: 'Back up a project to a file, or restore it', a: 'File › Download backup…: the whole project, or tick models (ticking a floor ticks its area plans, e.g. 33F = 3303 + 3307) — saved as a .eoscad file. File › Restore from file… (the project owner only): choose the file, pick which of its models, Compare to see what changes, then Restore. Everyone else in the project sees a 30 s countdown first (Cancel stops it), can’t edit while it runs, and is told when it’s done. It backs up the current state first (untick to skip), puts those models back as they were and is ONE undo step (Ctrl+Z). A cable to another model comes back only if the port at its other end is still free; the rest are listed. Issues and sheet revisions are never rolled back.' },
	{ area: 'project', q: 'Keep backups in the project, and clean them up', a: 'Project › Backups… › Back up now…: name it, tick the whole project or models, Back up. The list shows each backup’s size and the total (sort by Largest to see what takes the room). Per backup: Restore… (the project owner), Download (a .eoscad file), Rename, Delete — its maker or the owner deletes it; tick several to delete them at once. Deleting can’t be undone. Issuing makes one only when Back up the project with this issue is ticked (each is a full copy, so tick it for issues you may need to go back to); that issue then has Restore its backup… in Tables › Sheets › Issues.' },
	{ area: 'project', q: 'Bring in a drawing from Pages or the Sheets tool', a: 'File › Import legacy drawings… lists this project’s Pages models and Sheets-tool sheets (reading them changes nothing). Tick a Pages model to bring its boxes and walls (untick either) onto the level picked beside it — each goes on the cad layer of the same name, made if missing (a new layer starts frozen in the sheets that already exist); its opening boxes (doors, holes) become openings in the imported wall they sit in (a door-height one is a door, swinging as in Pages; one in no imported wall stays a box); its conduits and 2D shapes stay behind. Tick a sheet for a cad sheet with the same title, number and paper: its viewport shows the picked level’s plan or elevation, and its annotations come as notes tied to the viewport. An elevation clipped to a box (a comms room elevation) comes as a section on that box, named from the sheet (e.g. Comms1), so only what is inside the box shows. An odd scale (1:20.16) snaps to the nearest standard one, centred as before. The dialog lists what will come and what is left out (e.g. annotations on layers hidden in that viewport). Import is one undo step; things already imported are skipped, so importing again adds only what’s new.' },
]

/** The keyboard: from the shell's own list (ui/shellKeys.ts KEY_COMMANDS — what Help shows is what the keys do), plus
 *  the mouse and the keys tools take while drawing. */
const MOUSE: [string, string][] = [
	['Copy / Cut / Paste', 'Ctrl+C / X / V'], ['Paste with its middle at the pointer', 'Ctrl+Shift+V'],
	['Pan', 'Right- or middle-drag'], ['Zoom at the cursor', 'Wheel (ACAD input) · Ctrl / Alt + wheel, or right-button + wheel (EOS input)'], ['EOS input: pan up / down · sideways', 'Wheel · Shift+wheel'], ['EOS input: draw a line, run segment or dimension', 'Press at the first point, drag, release at the second (a click still works)'], ['ACAD / EOS input (status bar, kept per user)', 'Click ACAD / EOS at the right of the status bar'], ['15° steps / H-V / square', 'Shift while drawing or dragging (a dragged node keeps all its segments on 15°, a junction too)'],
	['No snap for this drag', 'Alt'], ['Finish a run', 'Enter · right-click'], ['Cancel what is drawn · deselect', 'Right-click on empty space'], ['Commands for something (selects it first)', 'Right-click it (Select tool)'],
	['Copy by dragging', 'Ctrl-drag'], ['Branch a run from a node', 'Ctrl-drag the node'], ['Pull a node off another run', 'Alt-drag the node'],
	['Window / crossing selection', 'Drag left → right / right → left'], ['Cycle through things stacked under the cursor', 'Click again on the same spot'],
	['Tables: pick rows', 'Click · Shift-click a range · Ctrl-click one more'], ['Tables: next / previous row', '↓ / ↑'], ['Tables: edit a cell', 'Double-click · F2 / Enter (the selected row)'],
	['Tables: save, then the next row / cell', 'Enter / Tab (Shift: back) · Esc cancels'], ['Tables: copy the rows for Excel', 'Ctrl+C'],
	['Rack view: focus a rack / the whole row', 'Double-click a rack / empty space'], ['Answer a question box', 'Enter = yes · Esc = Cancel (not while typing in a field)'],
]
export const SHORTCUTS: [string, string][] = [...KEY_COMMANDS.filter((k) => k.group !== 'Function keys').map((k): [string, string] => [k.label, k.keys]), ...MOUSE]

export const FKEYS: [string, string][] = KEY_COMMANDS.filter((k) => k.group === 'Function keys').map((k): [string, string] => [k.keys, k.label])
